      SUBROUTINE UPMISCC     UPDATE MISALIGNMENT TABLESCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8J.CIN'      INCLUDE 'ELM8M.CIN'C ---------------------------------------------------------------------      REAL            WORK(6,6)CC     MISALIGNMENT TABLE BEAM SIZEC      DO 100 N = 1, NMMAX      IF (.NOT. LNMT(N)) GO TO 100      DO 90 M = 1, 6C      DO 70 L1 = 1, 6      DO 70 L2 = 1, 6      S = 0.0      DO 65 L3 = 1, 6      LPL = 6*L3 + L2 - 6      L1L3 = 6*L3 + L1 - 6      S = S + RC2M(L1L3,M,N)*SIM(LPL,M,N)   65 CONTINUE      WORK(L1,L2) = S   70 CONTINUEC      DO 80 L1 = 1, 6      DO 80 L2 = 1, L1      LPL = 6*L1 + L2 - 6      LXL = 6*L2 + L1 - 6      S = 0.0      DO 75 L3 = 1, 6      L1L3 = 6*L3 + L1 - 6      S = S + RC2M(L1L3,M,N)*WORK(L2,L3)   75 CONTINUE      SIM(LPL,M,N) = S      SIM(LXL,M,N) = SIM(LPL,M,N)   80 CONTINUEC   90 CONTINUE      R2PM(N) = .FALSE.  100 CONTINUEC      RETURN      END